+                sat_id = sat_id.astype(str).item() if sat_id.size == 1 else str(sat_id)
+            kwrgs = {"sat_id": sat_id}
         except KeyError:
             # NWCSAF/PPS:
             kwrgs = {"platform_name": self.nc.attrs["platform"]}

